/// <reference path="../pb_data/types.d.ts" />
onBootstrap((e)=>{e.next();function install(a){const d=a.db();d.newQuery(`CREATE TRIGGER IF NOT EXISTS trg_locations_no_last_active_deactivate BEFORE UPDATE ON locations WHEN OLD.isActive = 1 AND NEW.isActive = 0 BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM locations WHERE userId = OLD.userId AND isActive = 1 AND id != OLD.id) = 0 THEN RAISE(ABORT, 'Debe mantener al menos una sede activa') END; END;`).execute();d.newQuery(`CREATE TRIGGER IF NOT EXISTS trg_locations_no_last_active_delete BEFORE DELETE ON locations WHEN OLD.isActive = 1 BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM locations WHERE userId = OLD.userId AND isActive = 1 AND id != OLD.id) = 0 THEN RAISE(ABORT, 'Debe mantener al menos una sede activa') END; SELECT CASE WHEN EXISTS (SELECT 1 FROM services WHERE locationId = OLD.id OR originLocationId = OLD.id) OR EXISTS (SELECT 1 FROM service_events WHERE fromLocationId = OLD.id OR toLocationId = OLD.id) THEN RAISE(ABORT, 'No se puede eliminar una sede con historial') END; END;`).execute();d.newQuery(`CREATE TRIGGER IF NOT EXISTS trg_locations_no_history_delete BEFORE DELETE ON locations BEGIN SELECT CASE WHEN EXISTS (SELECT 1 FROM services WHERE locationId = OLD.id OR originLocationId = OLD.id) OR EXISTS (SELECT 1 FROM service_events WHERE fromLocationId = OLD.id OR toLocationId = OLD.id) THEN RAISE(ABORT, 'No se puede eliminar una sede con historial') END; END;`).execute();}function tryI(){try{install($app);return true}catch(err){console.log("locations triggers not ready",err);return false}}if(tryI())return;try{cronAdd("install-location-triggers","* * * * *",()=>{if(tryI())try{cronRemove("install-location-triggers")}catch(_){}})}catch(_){}});onRecordUpdateRequest((e)=>{if(e.collection.name!=="locations")return e.next();const r=e.record,n=r.get("isActive");if(n===false||n===0||n==="false"){const u=r.get("userId"),a=$app.findRecordsByFilter("locations",`userId = {:uid} && isActive = {:active}`,"",100,0,{uid:u,active:true});if(a.some(x=>x.id===r.id)&&a.length<=1)throw new BadRequestError("Debe mantener al menos una sede activa")}e.next()},"locations");onRecordDeleteRequest((e)=>{if(e.collection.name!=="locations")return e.next();const r=e.record,u=r.get("userId"),s=$app.findRecordsByFilter("services",`locationId = {:lid} || originLocationId = {:lid}`,"",1,0,{lid:r.id}),l=$app.findRecordsByFilter("service_events",`fromLocationId = {:lid} || toLocationId = {:lid}`,"",1,0,{lid:r.id});if(s.length>0||l.length>0)throw new BadRequestError("No se puede eliminar una sede con historial de servicios o movimientos.");if(r.get("isActive")!==false){const a=$app.findRecordsByFilter("locations",`userId = {:uid} && isActive = {:active}`,"",100,0,{uid:u,active:true});if(a.length<=1)throw new BadRequestError("Debe mantener al menos una sede activa")}e.next()},"locations");
